      "quote": "Lorsque les oreilles du disciple sont prêtes à entendre, alors viennent les lèvres pour les emplir de Sagesse.",
      "reflection": "J'ai entendu cet enseignement cent fois avant de l'entendre une seule. Rien ne manquait aux mots - quelque chose manquait en moi. La Première Étape est la grande ouverture des oreilles : admettre que nous étions déconnectés nous a rendus prêts, et soudain les maîtres étaient partout - dans le tambour, dans la rivière, dans l'inconnu du cercle.",
