      "reflection": "L'invitation dit : pour cela tu es né. Chaque néophyte qui trouve notre cercle a reçu une telle lettre - le plus souvent déguisée en crise. Les noces ont toujours été sur ton calendrier ; le messager avait simplement des ailes que tu n'as pas reconnues.",
      "denomination": "Rosicrucien"
