      "quote": "Nous avons dépouillé toutes choses de leur mystère et de leur numinosité : plus rien n'est sacré.",
      "reflection": "Ce n'est pas un progrès, c'est une anesthésie. La première tâche de la cérémonie est de rendre aux choses leur voltage - la seconde est de te le rendre à toi.",
