      "quote": "À mesure que grandissait la compréhension scientifique, notre monde s'est déshumanisé. L'homme se sent isolé dans le cosmos, car il n'est plus impliqué dans la nature et a perdu son « identité inconsciente » émotionnelle avec les phénomènes naturels.",
