      "quote": "ฟ้าร้องไม่ใช่เสียงของเทพเจ้าผู้กริ้วอีกต่อไป สายฟ้าก็ไม่ใช่ศรล้างแค้นของพระองค์ ไม่มีแม่น้ำสายใดมีวิญญาณสถิต ไม่มีต้นไม้ต้นใดเป็นหลักชีวิตของมนุษย์ ไม่มีงูตัวใดเป็นร่างจำแลงของปัญญา ไม่มีถ้ำบนภูเขาแห่งใดเป็นที่พำนักของภูตผู้ยิ่งใหญ่",
