      "quote": "นักมานุษยวิทยาสอนผู้อื่นให้หลีกเลี่ยงกับดักของการยึดวัฒนธรรมตนเป็นศูนย์กลาง ด้วยการเรียนรู้ที่จะเข้าใจวัฒนธรรมหนึ่งตามสมมติฐานเรื่องความจริงของวัฒนธรรมนั้นเอง สิ่งที่ชามานตะวันตกพอจะพยายามสร้างขึ้นได้ในระดับหนึ่ง คือสัมพัทธนิยมทางปัญญา",
